// Normaliza el payload de WhatsApp Cloud API a una forma única.
// Meta anida el mensaje 4 niveles adentro y manda además eventos de
// 'status' (entregado/leído) por el mismo webhook. Si no se filtran, el
// flujo le contesta a sus propios acuses de recibo en bucle.

const body = $input.first().json.body ?? $input.first().json;

const value = body?.entry?.[0]?.changes?.[0]?.value;
const msg = value?.messages?.[0];

if (!msg) {
  // Evento de status, no un mensaje. Se corta acá.
  return [{ json: { skip: true, reason: 'sin mensaje entrante' } }];
}

if (msg.type !== 'text') {
  return [{
    json: {
      skip: false,
      unparseable: true,
      from: msg.from,
      name: value?.contacts?.[0]?.profile?.name ?? '',
      text: '',
      reason: `tipo de mensaje no soportado: ${msg.type}`,
    },
  }];
}

return [{
  json: {
    skip: false,
    unparseable: false,
    from: msg.from,
    name: value?.contacts?.[0]?.profile?.name ?? '',
    text: msg.text?.body ?? '',
    messageId: msg.id,
    receivedAt: new Date().toISOString(),
  },
}];

// Extrae fechas y cantidad de personas de texto libre en español.
//
// Deliberadamente conservador: ante la duda NO inventa fechas. Cotizar
// fechas equivocadas es peor que pedir que las repitan — el huésped se
// entusiasma con un precio que no corresponde y después hay que corregirlo.

const text = ($json.text || '').toLowerCase();

const MESES = {
  enero: 1, febrero: 2, marzo: 3, abril: 4, mayo: 5, junio: 6,
  julio: 7, agosto: 8, septiembre: 9, setiembre: 9, octubre: 10,
  noviembre: 11, diciembre: 12,
};

const pad = (n) => String(n).padStart(2, '0');
const hoy = new Date();

// Si el mes ya pasó, el huésped habla del año que viene.
function resolverAnio(mes, dia) {
  const esteAnio = hoy.getFullYear();
  const candidata = new Date(esteAnio, mes - 1, dia);
  return candidata < new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate())
    ? esteAnio + 1
    : esteAnio;
}

const fechas = [];

// "15 de noviembre", "15 y 16 de diciembre"
const reTexto = /(\d{1,2})(?:\s*(?:y|al|a|-)\s*(\d{1,2}))?\s*de\s*([a-záéíóú]+)/g;
let m;
while ((m = reTexto.exec(text)) !== null) {
  const mes = MESES[m[3]];
  if (!mes) continue;
  for (const d of [m[1], m[2]]) {
    if (!d) continue;
    const dia = Number(d);
    if (dia < 1 || dia > 31) continue;
    fechas.push(`${resolverAnio(mes, dia)}-${pad(mes)}-${pad(dia)}`);
  }
}

// "15/11", "15/11/2026"
const reNum = /(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?/g;
while ((m = reNum.exec(text)) !== null) {
  const dia = Number(m[1]);
  const mes = Number(m[2]);
  if (dia < 1 || dia > 31 || mes < 1 || mes > 12) continue;
  let anio = m[3] ? Number(m[3]) : resolverAnio(mes, dia);
  if (anio < 100) anio += 2000;
  fechas.push(`${anio}-${pad(mes)}-${pad(dia)}`);
}

const unicas = [...new Set(fechas)].sort();

// Personas. Hay que distinguir dos formas de contar, porque se restan distinto:
//   "somos 4, 2 niños"        → 4 es el TOTAL  → 2 adultos + 2 niños
//   "somos 2 adultos y 2 niños" → 2 son ADULTOS → 2 adultos + 2 niños
// Tratar el segundo caso como total deja 0 adultos y cotiza de menos.
let adultos = 2;
let adultosExplicitos = false;

const reAdultos = /(\d{1,2})\s*adultos?/;
const ma = reAdultos.exec(text);
if (ma) {
  const n = Number(ma[1]);
  if (n >= 1 && n <= 10) {
    adultos = n;
    adultosExplicitos = true;
  }
} else {
  const rePax = /(?:somos|para|seríamos|seriamos)\s*(\d{1,2})|(\d{1,2})\s*(?:personas|pax|huéspedes|huespedes)/;
  const mp = rePax.exec(text);
  if (mp) {
    const n = Number(mp[1] ?? mp[2]);
    if (n >= 1 && n <= 10) adultos = n;
  }
}

let ninos = 0;
const reNinos = /(\d{1,2})\s*(?:niños|ninos|chicos|menores)/;
const mn = reNinos.exec(text);
if (mn) {
  const n = Number(mn[1]);
  if (n >= 0 && n <= 6) {
    ninos = n;
    // Solo se resta si el número era un total, no si ya venía separado.
    if (!adultosExplicitos) adultos = Math.max(1, adultos - n);
  }
}

const mascota = /(perr|mascota|gat|cachorr)/.test(text);

// Hacen falta 2 fechas para cotizar. Con una sola no se asume una noche:
// se pregunta.
const completo = unicas.length >= 2;

return [{
  json: {
    ...$json,
    parsed: {
      completo,
      checkIn: completo ? unicas[0] : null,
      checkOut: completo ? unicas[unicas.length - 1] : null,
      adultos,
      ninos,
      mascota,
      fechasDetectadas: unicas,
    },
  },
}];

// ⚠️ DISPONIBILIDAD SIMULADA — LEER ANTES DE ACTIVAR
//
// Este nodo NO consulta disponibilidad real: devuelve un número fijo.
// No hay PMS ni channel manager conectado en este repo, y no hay
// credenciales para consultar el calendario de ninguna OTA.
//
// Con este nodo tal cual, el flujo puede confirmar disponibilidad de una
// habitación que ya está vendida. Eso es sobreventa, y una sobreventa
// cuesta la reserva, la reseña y — con 2 reseñas de base — buena parte de
// la reputación.
//
// POR ESO EL FLUJO NO CONFIRMA: cotiza y pasa a un humano para cerrar.
// Ver README de esta carpeta, sección "Antes de activar".
//
// Para conectarlo de verdad, reemplazar este nodo por una consulta al
// channel manager / PMS y devolver `roomsLeft` real.

const DISPONIBILIDAD_SIMULADA = 9;

return [{
  json: {
    ...$json,
    roomsLeft: DISPONIBILIDAD_SIMULADA,
    disponibilidadEsReal: false,
  },
}];

// Cotizador. Es una copia literal de sales-engine/lib/quote.js — n8n no
// puede importar módulos del repo, así que la lógica se pega acá.
//
// Si se toca el precio en un lado, hay que tocarlo en el otro. Las pruebas
// (`node --test sales-engine/lib/quote.test.js`) cubren el archivo del repo:
// correlas después de cualquier cambio y replicá acá.

const RULES = $vars.VICINA_PRICING_RULES
  ? JSON.parse($vars.VICINA_PRICING_RULES)
  : {
      baseRate: 69.0,
      dayOfWeek: { 0: 1.0, 1: 0.95, 2: 0.95, 3: 0.95, 4: 1.05, 5: 1.35, 6: 1.4 },
      seasons: [
        { code: 'SECA_ALTA', from: '12-15', to: '04-15', multiplier: 1.25 },
        { code: 'VERANILLO', from: '07-01', to: '08-31', multiplier: 1.1 },
        { code: 'BAJA', from: '09-01', to: '11-15', multiplier: 0.9 },
      ],
      holidays: {
        multiplier: 1.6,
        minimumNights: 2,
        dates: [
          { date: '2026-11-03', name: 'Separación de Colombia' },
          { date: '2026-11-04', name: 'Día de la Bandera' },
          { date: '2026-11-05', name: 'Día de Colón', multiplier: 1.75 },
          { date: '2026-11-10', name: 'Primer Grito de Independencia' },
          { date: '2026-11-28', name: 'Independencia de España' },
          { date: '2026-12-08', name: 'Día de la Madre' },
          { date: '2026-12-25', name: 'Navidad' },
          { date: '2026-12-31', name: 'Fin de Año', multiplier: 1.8 },
          { date: '2027-01-01', name: 'Año Nuevo' },
          { date: '2027-01-09', name: 'Día de los Mártires' },
          { date: '2027-02-06', name: 'Carnaval (sábado)', multiplier: 1.8 },
          { date: '2027-02-07', name: 'Carnaval (domingo)', multiplier: 1.8 },
          { date: '2027-02-08', name: 'Carnaval (lunes)', multiplier: 1.8 },
          { date: '2027-02-09', name: 'Carnaval (martes)', multiplier: 1.8 },
          { date: '2027-03-26', name: 'Viernes Santo' },
          { date: '2027-05-01', name: 'Día del Trabajo' },
        ],
      },
      scarcity: {
        tiers: [
          { maxRoomsLeft: 1, multiplier: 1.35 },
          { maxRoomsLeft: 2, multiplier: 1.2 },
          { maxRoomsLeft: 4, multiplier: 1.08 },
          { maxRoomsLeft: 9, multiplier: 1.0 },
        ],
      },
      leadTime: {
        lastMinute: { withinDays: 3, multiplier: 0.85, onlyIfRoomsLeftAtLeast: 4 },
        earlyBird: { beyondDays: 60, multiplier: 0.92 },
      },
      lengthOfStay: {
        tiers: [
          { minNights: 7, discount: 0.15 },
          { minNights: 4, discount: 0.1 },
          { minNights: 3, discount: 0.07 },
        ],
      },
      floor: { perNight: 69.0 },
    };

const RATES = { includedGuests: 2, extraAdult: 20.0, maxGuests: 4, petPerStay: 15.0 };

function parseCivilDate(iso) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso);
  if (!m) throw new Error(`Fecha inválida: ${iso}`);
  return new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
}
const toISO = (d) => {
  const p = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
};
function inSeasonRange(date, from, to) {
  const p = (n) => String(n).padStart(2, '0');
  const md = `${p(date.getMonth() + 1)}-${p(date.getDate())}`;
  return from <= to ? md >= from && md <= to : md >= from || md <= to;
}
function scarcityMultiplier(roomsLeft, scarcity) {
  const tiers = [...scarcity.tiers].sort((a, b) => a.maxRoomsLeft - b.maxRoomsLeft);
  for (const t of tiers) if (roomsLeft <= t.maxRoomsLeft) return t.multiplier;
  return 1.0;
}
const money = (n) => Math.round((n + Number.EPSILON) * 100) / 100;

const p = $json.parsed;
const roomsLeft = $json.roomsLeft;

const inDate = parseCivilDate(p.checkIn);
const outDate = parseCivilDate(p.checkOut);
const nights = Math.round((outDate - inDate) / 86400000);

if (nights < 1) {
  return [{ json: { ...$json, error: 'rango de fechas inválido' } }];
}
if (p.adultos + p.ninos > RATES.maxGuests) {
  return [{
    json: {
      ...$json,
      error: 'excede capacidad',
      needsMultipleRooms: true,
      roomsNeeded: Math.ceil((p.adultos + p.ninos) / RATES.maxGuests),
    },
  }];
}

const hoy = parseCivilDate(toISO(new Date()));
const leadDays = Math.round((inDate - hoy) / 86400000);
const holidayByDate = new Map(RULES.holidays.dates.map((h) => [h.date, h]));

const nightly = [];
const cursor = new Date(inDate);
for (let i = 0; i < nights; i++) {
  const iso = toISO(cursor);
  const mults = {};
  const season = RULES.seasons.find((s) => inSeasonRange(cursor, s.from, s.to));
  if (season) mults.season = season.multiplier;
  mults.dow = RULES.dayOfWeek[String(cursor.getDay())] ?? 1.0;
  const hol = holidayByDate.get(iso);
  if (hol) mults.holiday = hol.multiplier ?? RULES.holidays.multiplier;
  const sc = scarcityMultiplier(roomsLeft, RULES.scarcity);
  if (sc !== 1.0) mults.scarcity = sc;
  const { lastMinute, earlyBird } = RULES.leadTime;
  if (leadDays >= 0 && leadDays <= lastMinute.withinDays && roomsLeft >= lastMinute.onlyIfRoomsLeftAtLeast) {
    mults.lastMinute = lastMinute.multiplier;
  } else if (leadDays > earlyBird.beyondDays) {
    mults.earlyBird = earlyBird.multiplier;
  }
  let rate = RULES.baseRate;
  for (const v of Object.values(mults)) rate *= v;
  if (rate < RULES.floor.perNight) rate = RULES.floor.perNight;
  nightly.push({ date: iso, roomRate: money(rate), holiday: hol ? hol.name : null });
  cursor.setDate(cursor.getDate() + 1);
}

const roomTotal = money(nightly.reduce((s, n) => s + n.roomRate, 0));
const extraAdults = Math.max(0, p.adultos - RATES.includedGuests);
const extraAdultTotal = money(extraAdults * RATES.extraAdult * nights);
const petTotal = p.mascota ? RATES.petPerStay : 0;
const subtotal = roomTotal + extraAdultTotal + petTotal;
const tier = [...RULES.lengthOfStay.tiers].sort((a, b) => b.minNights - a.minNights).find((t) => nights >= t.minNights);
const losDiscount = tier ? money(subtotal * tier.discount) : 0;
const total = money(subtotal - losDiscount);

return [{
  json: {
    ...$json,
    quote: {
      nights,
      total,
      averageNightly: money(total / nights),
      roomTotal,
      extraAdultTotal,
      petTotal,
      losDiscount,
      holidayNights: nightly.filter((n) => n.holiday).map((n) => n.holiday),
    },
  },
}];

// Arma el mensaje. Sigue la estructura del playbook:
// disponibilidad → total → incluidos → UNA pregunta de cierre.

const q = $json.quote;
const p = $json.parsed;
const nombre = ($json.name || '').split(' ')[0];
const saludo = nombre ? `¡Hola ${nombre}!` : '¡Hola!';

if ($json.error === 'excede capacidad') {
  const texto = `${saludo} Cada habitación es para máximo 4 personas, así que ` +
    `para ustedes les armo ${$json.roomsNeeded} habitaciones 🌊\n\n` +
    `Decime y te paso el precio exacto por las ${$json.roomsNeeded}, con desayuno ` +
    `incluido para todos.`;
  return [{ json: { ...$json, reply: texto, needsHuman: true } }];
}

const noches = q.nights === 1 ? '1 noche' : `${q.nights} noches`;

let texto = `${saludo} 🌊 Sí, tengo disponibilidad para esas fechas.\n\n`;
texto += `📅 ${noches} · *$${q.total.toFixed(2)} en total*\n\n`;
texto += `Ya viene incluido, sin costo extra:\n`;
texto += `✓ Desayuno\n✓ Estacionamiento\n✓ Kayaks y equipo de snorkel\n`;
texto += `✓ Agua y kiosco\n✓ 20% de descuento en Mamaniva\n\n`;

if (p.ninos > 0) {
  texto += `Los menores de 11 no pagan, así que ya están incluidos 👨‍👩‍👧\n\n`;
}
if (p.mascota) {
  texto += `La mascota son $15 por toda la estadía, ya va en el total 🐕\n\n`;
}
if (q.losDiscount > 0) {
  texto += `Te apliqué $${q.losDiscount.toFixed(2)} de descuento por la estadía.\n\n`;
}

texto += `Estamos frente a la playa en La Angosta, a 15 min de Portobelo.\n\n`;
texto += `¿Te la aparto? Con tu nombre completo te la confirmo.`;

// Sin disponibilidad real verificada NO se afirma escasez. Escasez
// inventada en un lugar de 9 habitaciones se descubre al llegar.

return [{ json: { ...$json, reply: texto, needsHuman: true } }];

// No se detectaron fechas: se pide el dato que falta, sin inventar nada.

const nombre = ($json.name || '').split(' ')[0];
const saludo = nombre ? `¡Hola ${nombre}!` : '¡Hola!';

const texto = `${saludo} 🌊 Te cuento: estamos frente a la playa en La Angosta, ` +
  `a 15 min de Portobelo.\n\n` +
  `Habitaciones para hasta 4 personas, desde $69 la noche con desayuno, ` +
  `estacionamiento, kayaks y snorkel incluidos. Los menores de 11 no pagan.\n\n` +
  `¿Para qué fechas estabas viendo? Así te paso el precio exacto y te confirmo ` +
  `disponibilidad.`;

return [{ json: { ...$json, reply: texto, needsHuman: true } }];

parameters.jsonBody:
={{ JSON.stringify({ chat_id: $vars.TELEGRAM_CHAT_ID, text: `🔔 LEAD NUEVO

De: ${$json.name || 'sin nombre'} (${$json.from})
Dijo: ${$json.text}

${$json.quote ? `Cotizado: $${$json.quote.total} por ${$json.quote.nights} noche(s)` : 'Sin fechas — se le pidieron'}

⚠️ Falta CONFIRMAR disponibilidad real y cerrar.` }) }}
